```r
# ============================================================
# Steiger directionality analysis
# ============================================================
#
# Purpose:
#   Assess the direction of the association between the exposure
#   and outcome using the Steiger directionality test.
#
# Input:
#   Harmonized MR datasets generated by 02_Univariable_MR.
#
# Output:
#   results/sensitivity/steiger_results.csv
#
# Important:
#   - The same harmonized MR datasets used for the primary
#     random-effects IVW analyses are used here.
#   - Steiger testing is a diagnostic assessment of causal
#     direction, not a hard exclusion criterion.
#   - A failed or unsupported Steiger test does not automatically
#     exclude the MR analysis.
#   - No independent SNP selection is performed.
#   - No LD clumping is performed.
#   - No independent harmonisation is performed.
#
# Software:
#   R >= 4.5.0
#   TwoSampleMR 0.6.29
#
# ============================================================


# ------------------------------------------------------------
# 1. Packages
# ------------------------------------------------------------

required_packages <- c(
  "here",
  "TwoSampleMR",
  "readr",
  "dplyr"
)

missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0) {
  stop(
    "The following required packages are not installed: ",
    paste(missing_packages, collapse = ", "),
    call. = FALSE
  )
}

library(here)
library(TwoSampleMR)
library(readr)
library(dplyr)


# ------------------------------------------------------------
# 2. Project directories
# ------------------------------------------------------------

harmonized_dir <- here::here(
  "results",
  "primary_MR",
  "harmonized"
)

output_dir <- here::here(
  "results",
  "sensitivity"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)


# ------------------------------------------------------------
# 3. Input files
# ------------------------------------------------------------

harmonized_files <- c(
  # "CRP_on_VaD_overall.csv",
  # "CRP_on_VaD_undefined.csv",
  # "CRP_on_VaD_subcortical.csv",
  # "CRP_on_VaD_multi_infarct.csv",
  # "CRP_on_VaD_mixed.csv"
)

if (length(harmonized_files) == 0) {
  stop(
    paste0(
      "No harmonized MR input files have been specified.\n",
      "Please populate 'harmonized_files' with the exact output ",
      "files generated by 02_Univariable_MR."
    ),
    call. = FALSE
  )
}

harmonized_paths <- file.path(
  harmonized_dir,
  harmonized_files
)

missing_files <- harmonized_paths[
  !file.exists(harmonized_paths)
]

if (length(missing_files) > 0) {
  stop(
    "The following harmonized MR input files do not exist:\n",
    paste(missing_files, collapse = "\n"),
    call. = FALSE
  )
}


# ------------------------------------------------------------
# 4. Validate harmonized MR dataset
# ------------------------------------------------------------

validate_harmonized_data <- function(dat, file_name) {
  
  required_columns <- c(
    "SNP",
    "beta.exposure",
    "se.exposure",
    "beta.outcome",
    "se.outcome",
    "mr_keep"
  )
  
  missing_columns <- setdiff(
    required_columns,
    names(dat)
  )
  
  if (length(missing_columns) > 0) {
    stop(
      paste0(
        "Input file '", file_name,
        "' is missing required columns: ",
        paste(missing_columns, collapse = ", ")
      ),
      call. = FALSE
    )
  }
  
  dat <- dat %>%
    filter(
      !is.na(SNP),
      !is.na(beta.exposure),
      !is.na(se.exposure),
      !is.na(beta.outcome),
      !is.na(se.outcome),
      mr_keep == TRUE
    )
  
  if (nrow(dat) < 2) {
    return(NULL)
  }
  
  dat
}


# ------------------------------------------------------------
# 5. Check Steiger-specific variables
# ------------------------------------------------------------
#
# directionality_test() requires information about allele
# frequencies and sample sizes to estimate variance explained.
#
# These fields should have been retained during the primary
# harmonisation workflow.
# ------------------------------------------------------------

steiger_required_columns <- c(
  "eaf.exposure",
  "eaf.outcome",
  "samplesize.exposure",
  "samplesize.outcome"
)


# ------------------------------------------------------------
# 6. Run Steiger directionality analysis
# ------------------------------------------------------------

directionality_results <- list()

for (i in seq_along(harmonized_paths)) {
  
  input_file <- harmonized_paths[i]
  input_name <- basename(input_file)
  
  message(
    "Processing Steiger analysis: ",
    input_name
  )
  
  dat <- readr::read_csv(
    input_file,
    show_col_types = FALSE
  )
  
  dat <- validate_harmonized_data(
    dat = dat,
    file_name = input_name
  )
  
  if (is.null(dat)) {
    message(
      "  Fewer than 2 valid SNPs. Steiger analysis skipped."
    )
    next
  }
  
  missing_steiger_columns <- setdiff(
    steiger_required_columns,
    names(dat)
  )
  
  if (length(missing_steiger_columns) > 0) {
    
    warning(
      paste0(
        "Steiger analysis skipped for '",
        input_name,
        "' because the following required columns are missing: ",
        paste(missing_steiger_columns, collapse = ", ")
      ),
      call. = FALSE
    )
    
    next
  }
  
  # ----------------------------------------------------------
  # Run directionality test
  # ----------------------------------------------------------
  
  steiger_result <- tryCatch(
    {
      TwoSampleMR::directionality_test(dat)
    },
    warning = function(w) {
      
      message(
        "  Steiger warning for ",
        input_name,
        ": ",
        conditionMessage(w)
      )
      
      invokeRestart("muffleWarning")
    },
    error = function(e) {
      
      warning(
        "Steiger analysis failed for ",
        input_name,
        ": ",
        conditionMessage(e),
        call. = FALSE
      )
      
      NULL
    }
  )
  
  if (is.null(steiger_result) ||
      nrow(steiger_result) == 0) {
    
    message(
      "  No Steiger result returned."
    )
    
    next
  }
  
  # ----------------------------------------------------------
  # Retain the correct TwoSampleMR field:
  # correct_causal_direction
  # ----------------------------------------------------------
  
  if (
    !"correct_causal_direction" %in%
    names(steiger_result)
  ) {
    
    warning(
      paste0(
        "Steiger output for '",
        input_name,
        "' does not contain ",
        "'correct_causal_direction'. Please verify the ",
        "TwoSampleMR output structure."
      ),
      call. = FALSE
    )
  }
  
  steiger_result <- steiger_result %>%
    mutate(
      input_file = input_name,
      .before = 1
    )
  
  directionality_results[[length(directionality_results) + 1]] <-
    steiger_result
}


# ------------------------------------------------------------
# 7. Combine results
# ------------------------------------------------------------

directionality_results <- if (
  length(directionality_results) > 0
) {
  bind_rows(directionality_results)
} else {
  tibble()
}


# ------------------------------------------------------------
# 8. Save results
# ------------------------------------------------------------

output_file <- file.path(
  output_dir,
  "steiger_results.csv"
)

readr::write_csv(
  directionality_results,
  output_file,
  na = ""
)


# ------------------------------------------------------------
# 9. Completion message
# ------------------------------------------------------------

message(
  "\nSteiger directionality analysis completed."
)

message(
  "Results saved to: ",
  output_file
)
```
